import { describe, expect, it } from 'vitest';
import { createEngine } from '../../js/sim/engine.js';

// CHECKS: the top-level shape names the pool's primary backend — a stage-2
// 10.12-side fs edit lands only in servers[1].files while primaryFiles keeps
// 10.11's bytes (finding 1-06's counter-example), and a stage-1 edit IS the
// primary story (one backend, one shape, never a falsy empty-state claim).
describe('engine snapshot primary shape', () => {
  it("the primary shape names itself — 'primaryQueue' / 'primaryFiles' - the pool's primary-backend story, not an aggregate", () => {
    const engine = createEngine({ seed: 42, stage: 2 });
    engine.setWebFile('10.12', '/about', 'New body');
    const snap = engine.snapshot();
    expect(snap.primaryFiles['/about']).toBe('This is the about page');
    expect(snap.primaryQueue).toBe(snap.servers[0].queue);
    expect(snap.servers[1].files['/about']).toBe('New body');
    expect(snap.servers[0].files['/about']).toBe('This is the about page');

    const stage1 = createEngine({ seed: 42, stage: 1 });
    stage1.setWebFile('10.1', '/about', 'New body');
    expect(stage1.snapshot().primaryFiles['/about']).toBe('New body');
  });
});

